<script setup lang="ts">import {ref,computed} from 'vue';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import {useTask} from '../hooks/useTask';import {researchApi} from '../api/research';import {download} from '../api/client';import {fmt} from '../utils/format';const p=defineProps<{runs:any[];memos:any[];user:any;reloadResearch:()=>Promise<void>}>();const success=computed(()=>p.runs.filter(r=>r.status==='completed')),id=ref(0),name=ref('分类边界复核 '+new Date().toLocaleTimeString()),interpretation=ref('κ是相对类别基率的一致性，不是与金标准对照的准确率。'),next=ref('保持原三位标记者，独立复核争议试样，明确图谱类别边界。'),task=useTask(),exportLocale=ref<Record<number,string>>({}),run=computed(()=>success.value.find(r=>r.id===(id.value||success.value[0]?.id)));async function create(){await task.act(async()=>{await researchApi.createMemo({run_id:run.value.id,name:name.value,interpretation:interpretation.value,next_step:next.value});await p.reloadResearch()},'口径复核说明已提交')}async function approve(m:any,status:string){await task.act(async()=>{await researchApi.approve(m.id,{status,review_note:status==='approved'?'批准固定面板口径复核；一致性不代表准确率。':'请补充试样独立性与类别边界说明。'});await p.reloadResearch()},status==='approved'?'说明已批准':'说明已退回')}function snapshotCodes(m:any){const entries=m.result_snapshot.category_entries||(m.result_snapshot.categories||[]).map((name:string)=>({name,code:null}));return entries.map((e:any)=>e.name+(e.code?'·'+e.code:'·未编码')).join(' / ')}function downloadExport(m:any){const locale=exportLocale.value[m.id]||'';const suffix=locale?('?locale='+encodeURIComponent(locale)):'';const label=locale||'original';return task.act(()=>download('/memos/'+m.id+'/export'+suffix,'rater-review-'+m.id+'-'+label+'.csv'),'已导出批准快照CSV（'+label+'）')}</script><template><PageHeading index="05" title="把争议留给复核，把快照留在簿里。" description="人工解释和独立复核行动由负责人审阅；既有票修订不能改写已批准快照。"/><form v-if="user.role!=='viewer'" class="input-sheet memo-form" @submit.prevent="create"><div class="field-pair"><label>完成运行<select :value="run?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="r in success" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><label>说明名称<input v-model="name" required/></label></div><div class="field-pair"><label>人工解释<textarea v-model="interpretation" rows="3" required/></label><label>独立复核行动<textarea v-model="next" rows="3" required/></label></div><button class="primary" :disabled="task.state.busy||!run">提交口径复核说明 →</button></form><Notice v-bind="task.state"/><article class="memo-record" v-for="m in memos" :key="m.id"><div class="section-head"><h2>{{m.name}}</h2><Status :value="m.status"/></div><p>{{m.interpretation}}</p><p><strong>下一步 / </strong>{{m.next_step}}</p><div class="snapshot-line">冻结研究 {{m.result_snapshot.source_study.name}} / {{m.result_snapshot.specimen_count}}试样 / κ{{fmt(m.result_snapshot.kappa,6)}} / 有效{{m.result_snapshot.bootstrap.valid_repeats}}次<br/>冻结类别 {{snapshotCodes(m)}}<template v-if="m.result_snapshot.category_entries?.some((e:any)=>e.legacy)">（旧数据回读：显示名保留原样，编码按名称/同义名核对）</template></div><p v-if="m.review_note">审核 / {{m.review_note}}</p><div class="memo-actions"><template v-if="user.role==='admin'&&m.status==='draft'"><button @click="approve(m,'approved')">批准口径复核 ✓</button><button @click="approve(m,'rejected')">退回补充</button></template><template v-if="m.status==='approved'"><select v-model="exportLocale[m.id]" aria-label="导出名称语言"><option value="">原始快照名</option><option value="zh-CN">简体中文（按冻结版本）</option><option value="en">English（按冻结版本）</option></select><button @click="downloadExport(m)">导出批准快照 CSV ↗</button></template></div></article></template>
